import subprocess, sys, os, tempfile
EXE = os.environ.get('EXE', '/workspace/executable')
def probe(lines, extra=(), raw=False):
    d = tempfile.mkdtemp(dir='/tmp/h')
    p = os.path.join(d, 'f.txt')
    with open(p, 'wb') as f:
        for l in lines:
            if isinstance(l, str): l = l.encode('utf-8', 'surrogateescape')
            f.write(l + b'\n')
    r = subprocess.run([EXE, '--only-matching', *extra, 'f.txt'], cwd=d, capture_output=True)
    res = {}
    for line in r.stdout.split(b'\n'):
        if not line: continue
        parts = line.split(b':', 2)
        res.setdefault(int(parts[1]), []).append(parts[2] if raw else parts[2].decode('utf-8', 'backslashreplace'))
    os.remove(p); os.rmdir(d)
    return res
def show(lines, extra=()):
    res = probe(lines, extra)
    for i, l in enumerate(lines, 1):
        print(('MATCH ' + repr(res[i]) if i in res else 'no    ') + '  | ' + repr(l)[1:-1])
if __name__ == '__main__':
    data = sys.stdin.buffer.read().split(b'\n')
    if data and data[-1] == b'': data.pop()
    show([l.decode('utf-8', 'surrogateescape') for l in data])
