from math import comb, factorial
from functools import lru_cache
def p_binomial(n,x,p):
    left = x < n*p
    lo,hi = (0,x) if left else (x,n)
    tot=0.0
    for i in range(lo,hi+1):
        tot += factorial(n)/(factorial(n-i)*factorial(i)) * p**i * (1-p)**(n-i)
    return tot
def is_hex(s): return len(s)>=16 and all(c in '0123456789abcdefABCDEF' for c in s)
def is_cap_num(s): return len(s)>=16 and all(c.isupper() and c.isascii() or c.isdigit() and c.isascii() for c in s)
def p_class(s, base):
    def aux(lo,hi):
        cnt=sum(1 for c in s if lo<=c<=hi)
        return p_binomial(len(s), cnt, (ord(hi)-ord(lo)+1)/base)
    if base==16: return aux('0','9')
    cls=[('0','9'),('A','Z')] if base==36 else [('0','9'),('A','Z'),('a','z')]
    return min(aux(a,b) for a,b in cls)
@lru_cache(None)
def S2(n,k):
    if n==k: return 1
    if k==0 or n==0: return 0
    return k*S2(n-1,k)+S2(n-1,k-1)
def p_distinct(s, base):
    n=len(s); k=len(set(s))
    tot=0.0
    for i in range(1,k+1):
        r=float(base)
        for j in range(1,i): r*=(base-j)
        r*=S2(n,i)
        tot+=r
    return tot/float(base)**n
EOF
