from math import factorial
from functools import lru_cache
def p_binomial(n,x,p):
    left = x < n*p
    lo,hi = (0,x) if left else (x,n)
    tot=0.0
    for i in range(lo,hi+1):
        tot += factorial(n)/(factorial(n-i)*factorial(i)) * p**i * (1-p)**(n-i)
    return tot
@lru_cache(None)
def S2(n,k):
    if n==k: return 1
    if k==0 or n==0: return 0
    return k*S2(n-1,k)+S2(n-1,k-1)
def p_distinct(s, base):
    n=len(s); k=len(set(s))
    tot=0.0
    for i in range(1,k+1):
        r=float(base)
        for j in range(1,i): r*=(base-j)
        r*=S2(n,i)
        tot+=r
    return tot/float(base)**n
def cls_p(s, lo, hi, base, incl, nc_plus):
    if incl: cnt=sum(1 for c in s if lo<=c<=hi)
    else: cnt=sum(1 for c in s if lo<=c<hi)
    nc=ord(hi)-ord(lo)+(1 if nc_plus else 0)
    return p_binomial(len(s), cnt, nc/base)
def p_class(s, classes, base, incl, ncp):
    return min(cls_p(s,a,b,base,incl,ncp) for a,b in classes)
def decide(p, s):
    if p < 1e-5: return False
    if not any('0'<=c<='9' for c in s) and p < 1e-4: return False
    return True
EOF
