/// Returns true if the given byte string looks like a randomly generated
/// secret.
pub fn is_random(s: &[u8]) -> bool {
    let p = p_random(s);
    if p < 1.0 / 1e5 {
        return false;
    }
    let contains_num = s.iter().any(|c| c.is_ascii_digit());
    if !contains_num && p < 1.0 / 1e4 {
        return false;
    }
    true
}

fn is_hex_string(s: &[u8]) -> bool {
    s.len() >= 16 && s.iter().all(|c| c.is_ascii_hexdigit())
}

fn is_cap_and_numbers(s: &[u8]) -> bool {
    s.len() >= 16 && s.iter().all(|c| c.is_ascii_uppercase() || c.is_ascii_digit())
}

pub fn p_random(s: &[u8]) -> f64 {
    let base = if is_hex_string(s) {
        16.0
    } else if is_cap_and_numbers(s) {
        36.0
    } else {
        64.0
    };
    let mut p = p_random_char_class(s, base) * p_random_distinct_values(s, base);
    if base == 64.0 {
        // The bigram statistics only make sense for the full alphabet.
        p *= p_random_bigrams(s);
    }
    p
}

fn p_random_bigrams(s: &[u8]) -> f64 {
    let table = bigram_table();
    let mut num_bigrams = 0usize;
    if s.len() >= 2 {
        for w in s.windows(2) {
            if table[(w[0] as usize) << 8 | w[1] as usize] {
                num_bigrams += 1;
            }
        }
    }
    p_binomial(
        s.len(),
        num_bigrams,
        COMMON_BIGRAMS.len() as f64 / (64.0 * 64.0),
    )
}

fn p_random_char_class(s: &[u8], base: f64) -> f64 {
    if base == 16.0 {
        return p_random_char_class_aux(s, b'0', b'9', 16.0);
    }
    let classes_36: &[(u8, u8)] = &[(b'0', b'9'), (b'A', b'Z')];
    let classes_64: &[(u8, u8)] = &[(b'0', b'9'), (b'A', b'Z'), (b'a', b'z')];
    let classes = if base == 36.0 { classes_36 } else { classes_64 };
    let mut min_p = f64::INFINITY;
    for &(lo, hi) in classes {
        let p = p_random_char_class_aux(s, lo, hi, base);
        if p < min_p {
            min_p = p;
        }
    }
    min_p
}

/// Note that the upper bound of the range is exclusive when counting, while
/// the class size is computed inclusively.
fn p_random_char_class_aux(s: &[u8], lo: u8, hi: u8, base: f64) -> f64 {
    let count = s.iter().filter(|&&c| c >= lo && c < hi).count();
    let num_chars = (hi - lo + 1) as f64;
    p_binomial(s.len(), count, num_chars / base)
}

fn factorial(n: usize) -> f64 {
    let mut r = 1.0f64;
    for i in 2..=n {
        r *= i as f64;
    }
    r
}

/// Probability of an outcome at least as extreme as `x` successes out of
/// `n` trials with success probability `p` (one tailed).
fn p_binomial(n: usize, x: usize, p: f64) -> f64 {
    let left_tail = (x as f64) < n as f64 * p;
    let (lo, hi) = if left_tail { (0, x) } else { (x, n) };
    let fact_n = factorial(n);
    let mut total = 0.0f64;
    for i in lo..=hi {
        total += fact_n / (factorial(n - i) * factorial(i))
            * p.powi(i as i32)
            * (1.0 - p).powi((n - i) as i32);
    }
    total
}

fn count_distinct(s: &[u8]) -> usize {
    let mut seen = [false; 256];
    let mut n = 0;
    for &c in s {
        if !seen[c as usize] {
            seen[c as usize] = true;
            n += 1;
        }
    }
    n
}

/// Probability that a random string of the same length over an alphabet of
/// size `base` has at most as many distinct values as `s`.
fn p_random_distinct_values(s: &[u8], base: f64) -> f64 {
    let n = s.len();
    let k = count_distinct(s);
    let total_possible = base.powi(n as i32);
    // stirling[j] = S(m, j) for the current m (Stirling numbers of the
    // second kind), computed row by row up to m = n.
    let kmax = k.min(n);
    let mut stirling = vec![0.0f64; kmax + 1];
    if n == 0 {
        return 0.0 / total_possible;
    }
    stirling[0] = 1.0; // S(0, 0)
    for m in 1..=n {
        let upper = m.min(kmax);
        for j in (1..=upper).rev() {
            stirling[j] = j as f64 * stirling[j] + stirling[j - 1];
        }
        stirling[0] = 0.0;
    }
    let mut more_extreme = 0.0f64;
    for i in 1..=kmax {
        let mut outcomes = base;
        for j in 1..i {
            outcomes *= base - j as f64;
        }
        outcomes *= stirling[i];
        more_extreme += outcomes;
    }
    more_extreme / total_possible
}
