//! Recursive directory traversal honoring ignore files.
//!
//! Every directory that is visited (and every parent directory of a search
//! root) may contribute ignore rules from `.ignore`, `.gitignore` (inside git
//! repositories), `.git/info/exclude` and an optional custom ignore file. The
//! custom ignore file is given as an absolute path, so the same rules get
//! applied relative to every directory.

use std::collections::HashMap;
use std::ffi::OsString;
use std::fs::{self, File, FileType};
use std::io::{BufRead, BufReader};
use std::os::unix::ffi::OsStrExt;
use std::path::{Path, PathBuf};
use std::sync::Arc;

use ignore::gitignore::{Gitignore, GitignoreBuilder};

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum M {
    None,
    Ignore,
    Whitelist,
}

impl M {
    fn is_none(self) -> bool {
        self == M::None
    }
    fn or(self, other: M) -> M {
        if self.is_none() {
            other
        } else {
            self
        }
    }
}

fn to_m<T>(m: ignore::Match<T>) -> M {
    if m.is_ignore() {
        M::Ignore
    } else if m.is_whitelist() {
        M::Whitelist
    } else {
        M::None
    }
}

fn byte_strip_prefix<'a>(prefix: &[u8], path: &'a Path) -> Option<&'a Path> {
    let bytes = path.as_os_str().as_bytes();
    if bytes.len() >= prefix.len() && &bytes[..prefix.len()] == prefix {
        Some(Path::new(std::ffi::OsStr::from_bytes(&bytes[prefix.len()..])))
    } else {
        None
    }
}

/// Reads the lines of an ignore file into a builder. Reading stops at the
/// first line that isn't valid UTF-8; lines that don't parse are skipped.
pub fn add_ignore_file(builder: &mut GitignoreBuilder, path: &Path) {
    let file = match File::open(path) {
        Ok(f) => f,
        Err(_) => return,
    };
    for line in BufReader::new(file).lines() {
        match line {
            Ok(line) => {
                let _ = builder.add_line(Some(path.to_path_buf()), &line);
            }
            Err(_) => break,
        }
    }
}

pub fn new_builder(root: &Path) -> GitignoreBuilder {
    let mut b = GitignoreBuilder::new(root);
    b.allow_unclosed_class(false);
    b
}

fn create_gitignore(dir: &Path, file: &Path) -> Gitignore {
    let mut builder = new_builder(dir);
    if file.exists() {
        add_ignore_file(&mut builder, file);
    }
    match builder.build() {
        Ok(gi) => gi,
        Err(_) => Gitignore::empty(),
    }
}

fn resolve_git_commondir(dir: &Path, git_type: Option<FileType>) -> Option<PathBuf> {
    let git_dir = dir.join(".git");
    if !git_type.map_or(false, |ft| ft.is_file()) {
        return Some(git_dir);
    }
    let file = BufReader::new(File::open(&git_dir).ok()?);
    let line = file.lines().next()?.ok()?;
    let rest = line.strip_prefix("gitdir: ")?;
    let real_git_dir = PathBuf::from(rest);
    let file = BufReader::new(File::open(real_git_dir.join("commondir")).ok()?);
    let commondir = file.lines().next()?.ok()?;
    if commondir.starts_with('.') {
        Some(real_git_dir.join(commondir))
    } else {
        Some(PathBuf::from(commondir))
    }
}

struct Node {
    dir: PathBuf,
    parent: Option<Arc<Node>>,
    is_absolute_parent: bool,
    absolute_base: Option<Arc<PathBuf>>,
    custom: Gitignore,
    ignore: Gitignore,
    git_ignore: Gitignore,
    git_exclude: Gitignore,
    has_git: bool,
}

struct Parents<'a>(Option<&'a Node>);

impl<'a> Iterator for Parents<'a> {
    type Item = &'a Node;
    fn next(&mut self) -> Option<&'a Node> {
        let cur = self.0?;
        self.0 = cur.parent.as_deref();
        Some(cur)
    }
}

impl Node {
    fn parents(&self) -> Parents<'_> {
        Parents(Some(self))
    }
}

pub enum Visit<'a> {
    File(&'a Path),
    Error(String),
}

pub struct Walker {
    custom_file: Option<PathBuf>,
    global: Gitignore,
    root: Arc<Node>,
    cache: HashMap<OsString, Arc<Node>>,
}

impl Walker {
    pub fn new(custom_file: Option<PathBuf>) -> Walker {
        let global = {
            let builder = new_builder(Path::new(""));
            builder.build_global().0
        };
        let root = Arc::new(Node {
            dir: PathBuf::new(),
            parent: None,
            is_absolute_parent: true,
            absolute_base: None,
            custom: Gitignore::empty(),
            ignore: Gitignore::empty(),
            git_ignore: Gitignore::empty(),
            git_exclude: Gitignore::empty(),
            has_git: false,
        });
        Walker {
            custom_file,
            global,
            root,
            cache: HashMap::new(),
        }
    }

    fn child_node(&self, parent: &Arc<Node>, dir: &Path) -> Node {
        let git_type = dir.join(".git").metadata().ok().map(|md| md.file_type());
        let has_git = git_type.is_some();
        let custom = match &self.custom_file {
            Some(name) => create_gitignore(dir, &dir.join(name)),
            None => Gitignore::empty(),
        };
        let ignore = create_gitignore(dir, &dir.join(".ignore"));
        let git_ignore = create_gitignore(dir, &dir.join(".gitignore"));
        let git_exclude = match resolve_git_commondir(dir, git_type) {
            Some(git_dir) => create_gitignore(dir, &git_dir.join("info/exclude")),
            None => Gitignore::empty(),
        };
        Node {
            dir: dir.to_path_buf(),
            parent: Some(parent.clone()),
            is_absolute_parent: false,
            absolute_base: parent.absolute_base.clone(),
            custom,
            ignore,
            git_ignore,
            git_exclude,
            has_git,
        }
    }

    fn add_parents(&mut self, path: &Path) -> Arc<Node> {
        let absolute_base = match path.canonicalize() {
            Ok(p) => Arc::new(p),
            Err(_) => return self.root.clone(),
        };
        let mut parents = vec![];
        let mut p: &Path = &absolute_base;
        while let Some(parent) = p.parent() {
            parents.push(parent.to_path_buf());
            p = parent;
        }
        let mut ig = self.root.clone();
        for parent in parents.into_iter().rev() {
            if let Some(prebuilt) = self.cache.get(parent.as_os_str()) {
                ig = prebuilt.clone();
                continue;
            }
            let mut node = self.child_node(&ig, &parent);
            node.is_absolute_parent = true;
            node.has_git = parent.join(".git").exists();
            node.absolute_base = Some(absolute_base.clone());
            let node = Arc::new(node);
            self.cache.insert(parent.as_os_str().to_os_string(), node.clone());
            ig = node;
        }
        ig
    }

