            for n in node.parents().skip_while(|n| !n.is_absolute_parent) {
                if m_custom.is_none() {
                    m_custom = to_m(n.custom.matched(&abs_path, is_dir));
                }
                if m_ignore.is_none() {
                    m_ignore = to_m(n.ignore.matched(&abs_path, is_dir));
                }
                if any_git && !saw_git && m_gi.is_none() {
                    m_gi = to_m(n.git_ignore.matched(&abs_path, is_dir));
                }
                if any_git && !saw_git && m_gi_exclude.is_none() {
                    m_gi_exclude = to_m(n.git_exclude.matched(&abs_path, is_dir));
                }
                saw_git = saw_git || n.has_git;
            }
        }
        let m_global = if any_git {
            to_m(self.global.matched(path, is_dir))
        } else {
            M::None
        };
        m_custom.or(m_ignore).or(m_gi).or(m_gi_exclude).or(m_global)
    }

    fn should_skip(&self, node: &Node, path: &Path, is_dir: bool) -> bool {
        let stripped = byte_strip_prefix(b"./", path).unwrap_or(path);
        let m = self.matched_ignore(node, stripped, is_dir);
        if m.is_none() {
            let hidden = path
                .file_name()
                .map_or(false, |n| n.as_bytes().first() == Some(&b'.'));
            return hidden;
        }
        m == M::Ignore
    }

    /// Walks the given root path, calling `visit` for every file that should
    /// be searched and for every error encountered.
    pub fn walk(&mut self, root: &Path, visit: &mut dyn FnMut(Visit<'_>)) {
