            if md.is_file() {
                visit(Visit::File(root));
            }
            return;
        }
        let parent_ig = self.add_parents(root);
        // Explicit stack of (directory path, ignore matcher of its parent)
        // work items and files to visit, processed last-in first-out.
        enum Work {
            Dir(PathBuf, Arc<Node>),
            File(PathBuf),
        }
        let mut stack = vec![Work::Dir(root.to_path_buf(), parent_ig)];
        while let Some(work) = stack.pop() {
