//! Parsing of the `.secretsignore` file.
//!
//! The file has the format of a `.gitignore` file describing paths that
//! shouldn't be searched, optionally followed by a `[secrets]` section with
//! one secret per line that should not be reported.

use std::collections::HashSet;
use std::fs;
use std::io;
use std::path::Path;

pub const FILE_NAME: &str = ".secretsignore";
const SECRETS_HEADER: &str = "[secrets]\n";

pub struct SecretsIgnore {
    /// The ignore patterns, in gitignore format.
    pub paths: String,
    /// Whether the file had a `[secrets]` section.
    pub has_secrets_section: bool,
    /// Exact secrets that should not be reported.
    pub secrets: HashSet<Vec<u8>>,
}

pub fn load() -> io::Result<Option<SecretsIgnore>> {
    let path = Path::new(FILE_NAME);
    if !path.exists() {
        return Ok(None);
    }
    let contents = fs::read_to_string(path)?;
    let mut sections = contents.split(SECRETS_HEADER);
    let paths = sections.next().unwrap_or("").to_string();
    let (has_secrets_section, secrets) = match sections.next() {
        Some(secrets) => (
            true,
