//! Installation of the git pre-commit hook.

use std::fmt;
use std::fs::{self, OpenOptions};
use std::io::{self, Write};
use std::os::unix::fs::OpenOptionsExt;
use std::path::Path;

const HOOK_COMMAND: &str =
    "ripsecrets --strict-ignore `git diff --cached --name-only --diff-filter=ACM`\n";

pub enum InstallError {
    NoGitDir,
    AlreadyInstalled,
    Io(io::Error),
}

impl fmt::Display for InstallError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            InstallError::NoGitDir => write!(f, ".git directory not found"),
            InstallError::AlreadyInstalled => {
                write!(f, "pre-commit hook has already been installed")
            }
            InstallError::Io(err) => write!(f, "{}", err),
        }
    }
}

impl From<io::Error> for InstallError {
    fn from(err: io::Error) -> InstallError {
        InstallError::Io(err)
    }
}

pub fn install_pre_commit(repo: &Path) -> Result<(), InstallError> {
    let git_dir = repo.join(".git");
    if !git_dir.exists() {
        return Err(InstallError::NoGitDir);
    }
    let hook = git_dir.join("hooks").join("pre-commit");
    if hook.exists() {
        let contents = fs::read_to_string(&hook)?;
        if contents.contains(HOOK_COMMAND) {
            return Err(InstallError::AlreadyInstalled);
        }
    }
    let mut file = OpenOptions::new()
        .create(true)
        .append(true)
        .mode(0o744)
        .open(&hook)?;
    file.write_all(HOOK_COMMAND.as_bytes())?;
    Ok(())
}
