/// Probability of an outcome at least as extreme as `x` successes out of
/// `n` trials with success probability `p` (one tailed).
fn p_binomial(n: usize, x: usize, p: f64) -> f64 {
    let left_tail = (x as f64) < n as f64 * p;
    let (lo, hi) = if left_tail { (0, x) } else { (x, n) };
    let facts = factorials(n);
    let mut total = 0.0f64;
    for i in lo..=hi {
        total += facts[n] / (facts[n - i] * facts[i])
